package com.zerafix.telaestica;

import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import rikka.shizuku.Shizuku;

public class MainActivity extends Activity {
    static final int REQ_SHIZUKU=9001, ORANGE=Color.rgb(255,138,0), BG=Color.rgb(8,9,12), CARD=Color.rgb(19,22,28), FIELD=Color.rgb(29,32,39), MUTED=Color.rgb(150,155,165);
    LinearLayout content; TextView status,stretchValue,cropValue,profileTitle; EditText width,height,dpi; SeekBar stretch,crop; SharedPreferences prefs; String selectedGame="Sin juego seleccionado",selectedPackage="";
    int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} TextView tv(String s,float z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;} GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;} Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(13);b.setAllCaps(false);b.setBackground(bg(CARD,14));return b;} TextView section(String s){TextView t=tv(s,12,MUTED);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,dp(14),0,dp(6));return t;}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);prefs=getSharedPreferences("cat_resolution",0);selectedGame=prefs.getString("game",selectedGame);selectedPackage=prefs.getString("package","");buildShell();showHome();}
    void buildShell(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(18),dp(10),dp(18),dp(6));ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.ic_tiger);head.addView(icon,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout titles=new LinearLayout(this);titles.setOrientation(LinearLayout.VERTICAL);titles.setPadding(dp(10),0,0,0);TextView a=tv("CAT",22,Color.WHITE);a.setTypeface(Typeface.DEFAULT,Typeface.BOLD);TextView c=tv("RESOLUTION  •  Y9 PRIME",12,ORANGE);c.setTypeface(Typeface.DEFAULT,Typeface.BOLD);titles.addView(a);titles.addView(c);head.addView(titles,new LinearLayout.LayoutParams(0,dp(52),1));TextView gear=tv("⚙",25,Color.WHITE);gear.setGravity(Gravity.CENTER);gear.setOnClickListener(v->showSettings());head.addView(gear,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(head);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(16),0,dp(16),dp(12));sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setPadding(dp(8),dp(5),dp(8),dp(5));String[] labels={"⌂  INICIO","▣  JUEGOS","⚙  AJUSTES"};View.OnClickListener[] ls={v->showHome(),v->showGames(),v->showSettings()};for(int i=0;i<3;i++){TextView n=tv(labels[i],11,Color.WHITE);n.setGravity(Gravity.CENTER);n.setOnClickListener(ls[i]);nav.addView(n,new LinearLayout.LayoutParams(0,dp(50),1));}root.addView(nav);setContentView(root);}
    void clear(){content.removeAllViews();} LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);l.setBackground(bg(CARD,16));l.setPadding(dp(10),dp(8),dp(10),dp(8));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);l.setLayoutParams(p);return l;} EditText edit(String v){EditText e=new EditText(this);e.setText(v);e.setTextColor(Color.WHITE);e.setTextSize(16);e.setGravity(Gravity.CENTER);e.setSingleLine();e.setSelectAllOnFocus(true);e.setBackground(bg(FIELD,12));return e;}
    void showHome(){clear();TextView h=tv("Panel de control",24,Color.WHITE);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(h);content.addView(tv("Resolución, densidad y pantalla estirada",13,MUTED));content.addView(section("PERFIL ACTIVO"));LinearLayout game=card();profileTitle=tv(selectedGame,16,Color.WHITE);profileTitle.setTypeface(Typeface.DEFAULT,Typeface.BOLD);LinearLayout gt=new LinearLayout(this);gt.setOrientation(LinearLayout.VERTICAL);gt.addView(profileTitle);gt.addView(tv(selectedPackage.isEmpty()?"Selecciona un juego o perfil":selectedPackage,11,MUTED));game.addView(gt,new LinearLayout.LayoutParams(0,dp(58),1));Button pick=btn("CAMBIAR");pick.setOnClickListener(v->showGames());game.addView(pick,new LinearLayout.LayoutParams(dp(105),dp(48)));content.addView(game);content.addView(section("RESOLUCIÓN"));LinearLayout res=card();width=edit(prefs.getString("width","1080"));height=edit(prefs.getString("height","1920"));res.addView(width,new LinearLayout.LayoutParams(0,dp(54),1));TextView x=tv(" × ",18,MUTED);x.setGravity(Gravity.CENTER);res.addView(x);res.addView(height,new LinearLayout.LayoutParams(0,dp(54),1));content.addView(res);LinearLayout presets=new LinearLayout(this);for(String p:new String[]{"16:9","18:9","19.5:9","Ultra"}){Button b=btn(p);b.setTextSize(11);b.setOnClickListener(v->applyPreset(p));presets.addView(b,new LinearLayout.LayoutParams(0,dp(44),1));}content.addView(presets);content.addView(section("ESTIRAMIENTO"));LinearLayout s=card();stretch=new SeekBar(this);stretch.setMax(40);stretch.setProgress(prefs.getInt("stretch",20));stretchValue=tv((60+stretch.getProgress())+"%",15,ORANGE);stretchValue.setGravity(Gravity.CENTER);stretch.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){stretchValue.setText((60+p)+"%");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});s.addView(stretch,new LinearLayout.LayoutParams(-1,dp(42)));s.addView(stretchValue,new LinearLayout.LayoutParams(-1,dp(28)));content.addView(s);content.addView(section("RECORTE LATERAL"));LinearLayout cr=card();crop=new SeekBar(this);crop.setMax(30);crop.setProgress(prefs.getInt("crop",0));cropValue=tv(crop.getProgress()+"%",15,ORANGE);cropValue.setGravity(Gravity.CENTER);crop.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){cropValue.setText(p+"%");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});cr.addView(crop,new LinearLayout.LayoutParams(-1,dp(42)));cr.addView(cropValue,new LinearLayout.LayoutParams(-1,dp(28)));content.addView(cr);content.addView(section("DPI / DENSIDAD"));dpi=edit(prefs.getString("dpi",""));dpi.setHint("Automático");dpi.setHintTextColor(MUTED);content.addView(dpi,new LinearLayout.LayoutParams(-1,dp(52)));Button apply=btn("⚡  APLICAR RESOLUCIÓN");apply.setTextColor(Color.BLACK);apply.setBackground(bg(ORANGE,14));apply.setOnClickListener(v->applyNow());content.addView(apply,new LinearLayout.LayoutParams(-1,dp(56)));Button reset=btn("↺  RESTAURAR PANTALLA ORIGINAL");reset.setOnClickListener(v->resetDisplay());content.addView(reset,new LinearLayout.LayoutParams(-1,dp(52)));status=tv("Estado: listo",12,MUTED);status.setGravity(Gravity.CENTER);content.addView(status);}
    void applyPreset(String p){int w=1080,h=1920;if(p.equals("18:9"))h=2160;else if(p.equals("19.5:9"))h=2340;else if(p.equals("Ultra")){w=1280;h=2560;}width.setText(""+w);height.setText(""+h);}
    void showGames(){clear();TextView h=tv("Juegos",24,Color.WHITE);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(h);content.addView(tv("Selecciona una aplicación con lanzador",13,MUTED));Button detect=btn("＋  DETECTAR APLICACIONES");detect.setOnClickListener(v->gameDialog());content.addView(detect,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(section("PERFILES RÁPIDOS"));String[][] quick={{"Minecraft","1280","720","com.mojang.minecraftpe"},{"Free Fire","1440","720","com.dts.freefireth"},{"PUBG Mobile","1600","720","com.tencent.ig"},{"Call of Duty Mobile","1280","720","com.activision.callofduty.shooter"}};for(String[] q:quick){LinearLayout c=card();LinearLayout t=new LinearLayout(this);t.setOrientation(LinearLayout.VERTICAL);t.addView(tv(q[0],15,Color.WHITE));t.addView(tv(q[1]+" × "+q[2]+"  •  perfil",11,MUTED));c.addView(t,new LinearLayout.LayoutParams(0,dp(58),1));Button use=btn("USAR");use.setOnClickListener(v->{selectedGame=q[0];selectedPackage=q[3];prefs.edit().putString("game",selectedGame).putString("package",selectedPackage).putString("width",q[1]).putString("height",q[2]).apply();showHome();});c.addView(use,new LinearLayout.LayoutParams(dp(90),dp(44)));content.addView(c);}}
    void gameDialog(){PackageManager pm=getPackageManager();Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_LAUNCHER);List<android.content.pm.ResolveInfo> apps=pm.queryIntentActivities(i,PackageManager.MATCH_ALL);Collections.sort(apps,(a,b)->a.loadLabel(pm).toString().compareToIgnoreCase(b.loadLabel(pm).toString()));String[] names=new String[apps.size()];for(int k=0;k<apps.size();k++)names[k]=apps.get(k).loadLabel(pm).toString();new AlertDialog.Builder(this).setTitle("Aplicaciones instaladas").setItems(names,(d,w)->{selectedGame=names[w];selectedPackage=apps.get(w).activityInfo.packageName;prefs.edit().putString("game",selectedGame).putString("package",selectedPackage).apply();showHome();}).setNegativeButton("Cancelar",null).show();}
    void applyNow(){String w=width.getText().toString().trim(),h=height.getText().toString().trim();if(w.isEmpty()||h.isEmpty()){status.setText("Introduce ancho y alto");return;}try{int ww=Integer.parseInt(w),hh=Integer.parseInt(h);if(ww<240||hh<240||ww>10000||hh>10000)throw new Exception();int pct=60+stretch.getProgress();int cw=Math.max(240,Math.round(ww*pct/100f));int cp=crop.getProgress();if(cp>0)cw=Math.max(240,cw-Math.round(cw*cp/100f));String cmd="wm size "+cw+"x"+hh;String d=dpi.getText().toString().trim();if(!d.isEmpty()){int di=Integer.parseInt(d);if(di<80||di>1000)throw new Exception();cmd+="; wm density "+di;}prefs.edit().putString("width",w).putString("height",h).putString("dpi",d).putInt("stretch",stretch.getProgress()).putInt("crop",cp).apply();status.setText("Aplicando "+cw+" × "+hh+"...");runPrivileged(cmd,()->runOnUiThread(()->status.setText("✓ Pantalla aplicada")));}catch(Exception e){status.setText("Valores no válidos");}}
    void resetDisplay(){status.setText("Restaurando pantalla...");runPrivileged("wm size reset; wm density reset",()->runOnUiThread(()->status.setText("✓ Pantalla original restaurada")));}
    void runPrivileged(String cmd,Runnable done){new Thread(()->{try{if(!Shizuku.pingBinder()){runOnUiThread(()->status.setText("Shizuku no está iniciado"));return;}if(Shizuku.checkSelfPermission()!=PackageManager.PERMISSION_GRANTED){runOnUiThread(this::requestShizuku);return;}java.lang.reflect.Method m=Shizuku.class.getDeclaredMethod("newProcess",String[].class,String[].class,String.class);m.setAccessible(true);Process p=(Process)m.invoke(null,new Object[]{new String[]{"sh","-c",cmd},null,null});int code=p.waitFor();if(code!=0){String out=read(p.getErrorStream());if(out.isEmpty())out=read(p.getInputStream());throw new IOException(out.isEmpty()?"Shizuku rechazó el comando":out);}done.run();}catch(Exception e){runOnUiThread(()->status.setText("Error Shizuku: "+e.getMessage()));}}).start();}
    String read(InputStream in){try{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[1024];int n;while((n=in.read(x))>0)b.write(x,0,n);return b.toString().trim();}catch(Exception e){return "";}}
    void requestShizuku(){try{Shizuku.requestPermission(REQ_SHIZUKU);}catch(Exception e){new AlertDialog.Builder(this).setTitle("Shizuku requerido").setMessage("Abre Shizuku, inicia el servicio y vuelve a pulsar APLICAR.").setPositiveButton("OK",null).show();}}
    @Override protected void onResume(){super.onResume();if(status!=null&&Shizuku.pingBinder())status.setText(Shizuku.checkSelfPermission()==PackageManager.PERMISSION_GRANTED?"✓ Shizuku autorizado":"Shizuku conectado • falta autorizar");}
    void showSettings(){clear();TextView h=tv("Ajustes",24,Color.WHITE);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(h);content.addView(section("SHIZUKU"));Button b=btn("ABRIR / CONFIGURAR SHIZUKU");b.setOnClickListener(v->{try{startActivity(getPackageManager().getLaunchIntentForPackage("moe.shizuku.privileged.api"));}catch(Exception e){Toast.makeText(this,"Instala Shizuku primero",Toast.LENGTH_LONG).show();}});content.addView(b,new LinearLayout.LayoutParams(-1,dp(54)));content.addView(section("ESTADO"));content.addView(tv(Shizuku.pingBinder()?"Shizuku conectado":"Shizuku no iniciado",14,Color.WHITE));Button p=btn("SOLICITAR PERMISO DE SHIZUKU");p.setOnClickListener(v->requestShizuku());content.addView(p,new LinearLayout.LayoutParams(-1,dp(54)));content.addView(section("RESTAURACIÓN"));content.addView(tv("La aplicación usa wm size y wm density mediante Shizuku y permite restaurar los valores del sistema.",13,MUTED));}
}
